<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Services\AuditLogger;
use App\Services\OrderPricingService;
use App\Services\OperationalLedger;

class FactoryController extends Controller
{
    public function index(Request $request)
    {
        $page = $request->query('page_name', 'dashboard');
        if ($request->user()->role==='Operational Staff' && in_array($page,['customers','customer','suppliers','supplier','orders','reports','transactions','audit','settings','users','imports'])) abort(403);
        if (in_array($page,['users','settings']) && $request->user()->role !== 'Administrator / Owner') abort(403);
        if (in_array($page,['reports','transactions']) && $request->user()->role === 'Operational Staff') abort(403);
        $data = ['page' => $page, 'query' => $request->query(), 'editing' => false, 'editItems' => collect()];
        if ($page === 'dashboard') {
            $data += [
                'customers' => DB::table('customers')->where('active', 1)->count(), 'suppliers' => DB::table('suppliers')->where('active', 1)->count(),
                'activeOrders' => DB::table('orders')->whereNotIn('status', ['Delivered','Cancelled'])->count(),
                'ready' => DB::table('orders')->where('status','Ready for Delivery')->count(),
                'receivable' => DB::table('customers')->sum('opening_balance') + DB::table('orders')->whereNotIn('status',['Cancelled'])->sum('total') - DB::table('customer_payments')->whereNull('voided_at')->sum('amount'),
                'payable' => DB::table('suppliers')->sum('opening_balance') + DB::table('purchases')->where('status','Open')->sum('total') - DB::table('supplier_payments')->whereNull('voided_at')->sum('amount'),
                'receivedToday' => DB::table('customer_payments')->whereNull('voided_at')->whereDate('paid_at', today())->sum('amount'), 'paidToday' => DB::table('supplier_payments')->whereNull('voided_at')->whereDate('paid_at', today())->sum('amount'),
                'recentOrders' => DB::table('orders')->join('customers','customers.id','=','orders.customer_id')->select('orders.*','customers.name as customer')->latest('orders.ordered_at')->limit(7)->get(),
                'recentCustomerPayments' => DB::table('customer_payments')->whereNull('voided_at')->join('customers','customers.id','=','customer_payments.customer_id')->select('customer_payments.*','customers.name as party')->latest('paid_at')->limit(5)->get(),
                'recentSupplierPayments' => DB::table('supplier_payments')->whereNull('voided_at')->join('suppliers','suppliers.id','=','supplier_payments.supplier_id')->select('supplier_payments.*','suppliers.name as party')->latest('paid_at')->limit(5)->get(),
            ];
        } elseif ($page === 'customers') {
            $q = DB::table('customers')->when($request->search, fn($b,$s)=>$b->where(fn($x)=>$x->where('name','like',"%$s%")->orWhere('business_name','like',"%$s%")->orWhere('phone','like',"%$s%")->orWhere('code','like',"%$s%")))->orderBy('name');
            $data['rows'] = $q->paginate(12)->withQueryString();
        } elseif ($page === 'suppliers') {
            $q = DB::table('suppliers')->when($request->search, fn($b,$s)=>$b->where(fn($x)=>$x->where('name','like',"%$s%")->orWhere('business_name','like',"%$s%")->orWhere('phone','like',"%$s%")->orWhere('code','like',"%$s%")))->orderBy('name'); $data['rows'] = $q->paginate(12)->withQueryString();
        } elseif ($page === 'orders') {
            $q = DB::table('orders')->join('customers','customers.id','=','orders.customer_id')->select('orders.*','customers.name as customer')
                ->when($request->search,fn($b,$s)=>$b->where(fn($x)=>$x->where('number','like',"%$s%" )->orWhere('customers.name','like',"%$s%")))
                ->when($request->customer_id,fn($b,$s)=>$b->where('orders.customer_id',$s))
                ->when($request->status,fn($b,$s)=>$b->where('orders.status',$s))
                ->when($request->payment_status,function($b,$s){$comparison=$s==='Paid'?'>=':'<';$b->whereRaw('(select coalesce(sum(a.amount),0) from customer_payment_allocations a join customer_payments p on p.id=a.customer_payment_id where a.order_id=orders.id and p.voided_at is null) '.$comparison.' orders.total');})
                ->when($request->outstanding,fn($b)=>$b->whereRaw('(select coalesce(sum(a.amount),0) from customer_payment_allocations a join customer_payments p on p.id=a.customer_payment_id where a.order_id=orders.id and p.voided_at is null) < orders.total'))
                ->when($request->from,fn($b,$s)=>$b->whereDate('ordered_at','>=',$s))->when($request->to,fn($b,$s)=>$b->whereDate('ordered_at','<=',$s))->latest('ordered_at');
            $data['rows']=$q->paginate(12)->withQueryString(); $data['customersList']=DB::table('customers')->where('active',1)->orderBy('name')->get(); $data['orderReceivables']=DB::table('customers')->sum('opening_balance')+DB::table('orders')->whereNotIn('status',['Cancelled'])->sum('total')-DB::table('customer_payments')->whereNull('voided_at')->sum('amount'); $data['periodPayments']=DB::table('customer_payments')->whereNull('voided_at')->when($request->from,fn($b,$d)=>$b->whereDate('paid_at','>=',$d))->when($request->to,fn($b,$d)=>$b->whereDate('paid_at','<=',$d))->sum('amount');
        } elseif ($page === 'purchases') {
            abort_unless($request->user()->role !== 'Operational Staff', 403);
            $data['rows'] = DB::table('purchases')->join('suppliers', 'suppliers.id', '=', 'purchases.supplier_id')
                ->select('purchases.*', 'suppliers.name as supplier', 'suppliers.code as supplier_code')
                ->when($request->search, fn($q, $s) => $q->where(fn($w) => $w->where('purchases.number', 'like', "%$s%")
                    ->orWhere('purchases.description', 'like', "%$s%")
                    ->orWhere('suppliers.name', 'like', "%$s%")))
                ->when($request->supplier_id, fn($q, $id) => $q->where('purchases.supplier_id', $id))
                ->when($request->from, fn($q, $d) => $q->whereDate('purchased_at', '>=', $d))
                ->when($request->to, fn($q, $d) => $q->whereDate('purchased_at', '<=', $d))
                ->latest('purchased_at')->paginate(15)->withQueryString();
            $data['suppliersList'] = DB::table('suppliers')->where('active', 1)->orderBy('name')->get();
            $data['purchaseTotal'] = DB::table('purchases')->where('status', 'Open')->sum('total');
            $data['supplierPaymentsTotal'] = DB::table('supplier_payments')->whereNull('voided_at')->sum('amount');
        } elseif ($page === 'new-purchase') {
            abort_unless($request->user()->role !== 'Operational Staff', 403);
            $data['supplierList'] = DB::table('suppliers')->where('active', 1)->orderBy('name')->get();
            $data['selectedSupplier'] = $request->supplier_id;
        } elseif ($page === 'customer') {
            $data['record']=DB::table('customers')->where('id',$request->id)->first() ?? abort(404); $data['orders']=DB::table('orders')->where('customer_id',$request->id)->latest('ordered_at')->get(); $data['payments']=DB::table('customer_payments')->leftJoin('customer_payment_allocations','customer_payment_allocations.customer_payment_id','=','customer_payments.id')->leftJoin('orders','orders.id','=','customer_payment_allocations.order_id')->select('customer_payments.*','orders.number as order_number','customer_payment_allocations.amount as allocated_amount')->where('customer_payments.customer_id',$request->id)->whereNull('customer_payments.voided_at')->latest('paid_at')->get();
        } elseif ($page === 'supplier') {
            $data['record']=DB::table('suppliers')->where('id',$request->id)->first() ?? abort(404); $data['purchases']=DB::table('purchases')->where('supplier_id',$request->id)->latest('purchased_at')->get(); $data['payments']=DB::table('supplier_payments')->leftJoin('supplier_payment_allocations','supplier_payment_allocations.supplier_payment_id','=','supplier_payments.id')->leftJoin('purchases','purchases.id','=','supplier_payment_allocations.purchase_id')->select('supplier_payments.*','purchases.number as purchase_number','supplier_payment_allocations.amount as allocated_amount')->where('supplier_payments.supplier_id',$request->id)->whereNull('supplier_payments.voided_at')->latest('paid_at')->get();
        } elseif ($page === 'new-order' || $page === 'edit-order') { $data['customersList']=DB::table('customers')->where('active',1)->orderBy('name')->get(); $data['editing']=$page==='edit-order'; $data['selectedCustomer']=$request->customer_id; if($page==='edit-order'){ $data['record']=DB::table('orders')->where('id',$request->id)->first() ?? abort(404); abort_unless($data['record']->status==='Pending',403,'Orders may only be edited before production begins.'); $data['selectedCustomer']=$data['record']->customer_id; $data['editItems']=DB::table('order_items')->where('order_id',$request->id)->get(); } }
        elseif ($page === 'order') { $data['record']=DB::table('orders')->join('customers','customers.id','=','orders.customer_id')->select('orders.*','customers.name as customer','customers.code as customer_code')->where('orders.id',$request->id)->first() ?? abort(404); $data['items']=DB::table('order_items')->where('order_id',$request->id)->get(); $data['payments']=DB::table('customer_payments')->join('customer_payment_allocations','customer_payment_allocations.customer_payment_id','=','customer_payments.id')->where('customer_payment_allocations.order_id',$request->id)->whereNull('customer_payments.voided_at')->select('customer_payments.*','customer_payment_allocations.amount as allocated_amount')->latest('paid_at')->get(); $data['paid']=DB::table('customer_payment_allocations')->join('customer_payments','customer_payments.id','=','customer_payment_allocations.customer_payment_id')->where('customer_payment_allocations.order_id',$request->id)->whereNull('customer_payments.voided_at')->sum('customer_payment_allocations.amount'); }
        elseif ($page === 'new-customer' || $page === 'new-supplier') { $data['record']=$request->id ? DB::table($page==='new-customer'?'customers':'suppliers')->where('id',$request->id)->first() ?? abort(404) : null; }
        elseif ($page === 'new-purchase') { $data['supplierList']=DB::table('suppliers')->where('active',1)->orderBy('name')->get(); }
        elseif ($page === 'transactions') { abort_unless($request->user()->role!=='Operational Staff',403); $data['customerTransactions']=DB::table('customer_payments')->join('customers','customers.id','=','customer_payments.customer_id')->whereNull('voided_at')->select('customer_payments.*','customers.name as party_name','customers.code as party_code')->when($request->from,fn($q,$v)=>$q->whereDate('paid_at','>=',$v))->when($request->to,fn($q,$v)=>$q->whereDate('paid_at','<=',$v))->latest('paid_at')->paginate(20,['*'],'customer_page')->withQueryString(); $data['supplierTransactions']=DB::table('supplier_payments')->join('suppliers','suppliers.id','=','supplier_payments.supplier_id')->whereNull('voided_at')->select('supplier_payments.*','suppliers.name as party_name','suppliers.code as party_code')->when($request->from,fn($q,$v)=>$q->whereDate('paid_at','>=',$v))->when($request->to,fn($q,$v)=>$q->whereDate('paid_at','<=',$v))->latest('paid_at')->paginate(20,['*'],'supplier_page')->withQueryString(); }
        elseif ($page === 'allocate') { abort_unless($request->user()->role!=='Operational Staff',403); $type=$request->query('type','customer'); abort_unless(in_array($type,['customer','supplier']),404); $data['allocationType']=$type; $table=$type.'_payments'; $data['allocationPayment']=DB::table($table)->where('id',$request->payment_id)->whereNull('voided_at')->first() ?? abort(404); $data['allocationTargets']=$type==='customer'?DB::table('orders')->where('customer_id',$data['allocationPayment']->customer_id)->whereNotIn('status',['Cancelled'])->whereRaw('total > (select coalesce(sum(a.amount),0) from customer_payment_allocations a join customer_payments p on p.id=a.customer_payment_id where a.order_id=orders.id and p.voided_at is null)')->orderByDesc('ordered_at')->get():DB::table('purchases')->where('supplier_id',$data['allocationPayment']->supplier_id)->where('status','Open')->whereRaw('total > (select coalesce(sum(a.amount),0) from supplier_payment_allocations a join supplier_payments p on p.id=a.supplier_payment_id where a.purchase_id=purchases.id and p.voided_at is null)')->orderByDesc('purchased_at')->get(); }
        elseif ($page === 'production') { $data['orders']=DB::table('orders')->join('customers','customers.id','=','orders.customer_id')->select('orders.*','customers.name as customer')->whereIn('orders.status',['Pending','In Production','Ready for Delivery'])->orderBy('expected_at')->paginate(20)->withQueryString(); }
        elseif ($page === 'users') { abort_unless($request->user()->role==='Administrator / Owner',403); $data['users']=DB::table('users')->orderBy('name')->paginate(20); }
        elseif ($page === 'settings') { abort_unless($request->user()->role==='Administrator / Owner',403); $data['settings']=DB::table('business_settings')->orderBy('key')->get(); }
        elseif ($page === 'audit') { abort_unless($request->user()->role==='Administrator / Owner',403); $data['logs']=DB::table('audit_logs')->leftJoin('users','users.id','=','audit_logs.user_id')->select('audit_logs.*','users.name as actor')->latest('audit_logs.created_at')->paginate(30); }
        elseif ($page === 'imports') { abort_unless($request->user()->role==='Administrator / Owner',403); $type=$request->query('type','customer'); abort_unless(in_array($type,['customer','supplier']),404); $data['importType']=$type; $data['importPreview']=$request->session()->get('factory_import_'.$type); }
        elseif ($page === 'reports') { $data['ordersByStatus']=DB::table('orders')->select('status',DB::raw('count(*) as count'),DB::raw('sum(total) as total'))->groupBy('status')->get(); $data['customerBalances']=DB::table('customers')->select('customers.*')->orderBy('name')->get(); $data['supplierBalances']=DB::table('suppliers')->select('suppliers.*')->orderBy('name')->get(); $data['customerPayments']=DB::table('customer_payments')->whereNull('voided_at')->latest('paid_at')->limit(100)->get(); $data['supplierPayments']=DB::table('supplier_payments')->whereNull('voided_at')->latest('paid_at')->limit(100)->get(); }
        $data['ledger'] = app(OperationalLedger::class);
        return view('factory', $data);
    }

    public function saveParty(Request $request, string $type, AuditLogger $audit)
    {
        abort_unless(in_array($type,['customer','supplier']),404); $table=$type.'s';
        $v=$request->validate(['name'=>'required|string|max:160','business_name'=>'nullable|string|max:160','phone'=>'nullable|string|max:60','address'=>'nullable|string|max:2000','notes'=>'nullable|string|max:4000']);
        if ($request->id) { $before=(array)DB::table($table)->where('id',$request->id)->first() ?? abort(404); DB::table($table)->where('id',$request->id)->update($v+['updated_at'=>now()]); $id=$request->id; $audit->record('updated',$type,$id,$before,$v); }
        else { $id=DB::transaction(function()use($table,$type,$v){$last=(int)DB::table($table)->lockForUpdate()->max('id')+1; return DB::table($table)->insertGetId($v+['code'=>strtoupper(substr($type,0,3)).'-'.str_pad((string)$last,4,'0',STR_PAD_LEFT),'created_at'=>now(),'updated_at'=>now()]);}); $audit->record('created',$type,$id,null,$v); }
        return redirect('/?page_name='.$type.'&id='.$id)->with('success',ucfirst($type).' saved successfully.');
    }

    public function toggleParty(Request $request,string $type,int $id,AuditLogger $audit)
    {
        abort_unless(in_array($type,['customer','supplier']),404);$table=$type.'s';$party=DB::table($table)->where('id',$id)->first() ?? abort(404);$active=!$party->active;DB::table($table)->where('id',$id)->update(['active'=>$active,'updated_at'=>now()]);$audit->record($active?'activated':'archived',$type,$id,['active'=>(bool)$party->active],['active'=>$active]);return back()->with('success',ucfirst($type).($active?' restored.':' archived.'));
    }

    public function saveOrder(Request $request, OrderPricingService $pricing, AuditLogger $audit, \App\Services\DocumentNumber $numbers)
    {
        $v=$request->validate(['customer_id'=>'required|exists:customers,id','expected_at'=>'nullable|date','notes'=>'nullable|string|max:4000','initial_payment'=>'nullable|numeric|min:0|decimal:0,2','payment_method'=>'nullable|string|max:40','items'=>'required|array|min:1','items.*.product_type'=>'required|string|max:120','items.*.paper_grade'=>'nullable|string|max:120','items.*.length'=>'nullable|numeric|min:0|decimal:0,2','items.*.width'=>'nullable|numeric|min:0|decimal:0,2','items.*.height'=>'nullable|numeric|min:0|decimal:0,2','items.*.unit'=>'required|string|max:20','items.*.quantity'=>'required|integer|min:1','items.*.unit_price'=>'required|numeric|min:0|decimal:0,2','items.*.notes'=>'nullable|string|max:1000']);
        $total=$pricing->orderTotal($v['items']); abort_if(bccomp((string)($v['initial_payment']??0),$total,2)>0,422,'Initial payment cannot exceed the order total.');
        $orderId=DB::transaction(function() use($v,$request,$pricing,$total,$numbers) { $number=$numbers->next('order','ORD'); $id=DB::table('orders')->insertGetId(['number'=>$number,'customer_id'=>$v['customer_id'],'ordered_at'=>now(),'expected_at'=>$v['expected_at']??null,'status'=>'Pending','delivery_status'=>'Pending','total'=>$total,'notes'=>$v['notes']??null,'created_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]); foreach($v['items'] as $item) DB::table('order_items')->insert($item+['order_id'=>$id,'line_total'=>$pricing->lineTotal($item['quantity'],$item['unit_price']),'created_at'=>now(),'updated_at'=>now()]); $pay=(float)($v['initial_payment']??0); if($pay>0) { $paymentId=DB::table('customer_payments')->insertGetId(['customer_id'=>$v['customer_id'],'order_id'=>$id,'paid_at'=>now(),'amount'=>$pay,'method'=>$v['payment_method']??'Cash','number'=>$numbers->next('customer_payment','CR'),'recorded_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]); DB::table('customer_payment_allocations')->insert(['customer_payment_id'=>$paymentId,'order_id'=>$id,'amount'=>$pay,'created_at'=>now(),'updated_at'=>now()]); } DB::table('order_status_histories')->insert(['order_id'=>$id,'from_status'=>null,'to_status'=>'Pending','changed_at'=>now(),'changed_by'=>auth()->user()?->name,'created_at'=>now(),'updated_at'=>now()]); return $id; });
        $audit->record('created','order',$orderId,null,['number'=>DB::table('orders')->where('id',$orderId)->value('number'),'total'=>$total]);
        return redirect('/?page_name=order&id='.$orderId)->with('success','Order created. Prices are manually entered and must be approved by the factory.');
    }

    public function updateOrder(Request $request, int $id)
    {
        $v=$request->validate(['status'=>'required|in:Pending,In Production,Ready for Delivery,Delivered,Cancelled','delivery_status'=>'required|in:Pending,Scheduled,Delivered,Collected','delivery_method'=>'nullable|string|max:80','dispatched_at'=>'nullable|date','delivery_notes'=>'nullable|string|max:4000']); abort_if(auth()->user()->role==='Operational Staff' && $v['status']==='Cancelled',403); $oldRow=DB::table('orders')->where('id',$id)->first() ?? abort(404); if($v['status']==='Cancelled'){ $allocated=DB::table('customer_payment_allocations')->join('customer_payments','customer_payments.id','=','customer_payment_allocations.customer_payment_id')->where('order_id',$id)->whereNull('voided_at')->sum('customer_payment_allocations.amount'); abort_if(bccomp((string)$allocated,'0.00',2)>0,422,'This order has allocated payments. Reallocate or refund those payments before cancellation.'); } DB::transaction(function()use($id,$v,$oldRow){ DB::table('orders')->where('id',$id)->update($v+['updated_at'=>now()]); if($oldRow->status!==$v['status']) DB::table('order_status_histories')->insert(['order_id'=>$id,'from_status'=>$oldRow->status,'to_status'=>$v['status'],'changed_at'=>now(),'changed_by'=>auth()->user()->name,'created_at'=>now(),'updated_at'=>now()]); }); app(AuditLogger::class)->record('updated','order',$id,(array)$oldRow,$v); return back()->with('success','Order and delivery status updated.');
    }

    public function updateOrderDetails(Request $request, int $id, OrderPricingService $pricing, AuditLogger $audit)
    {
        $v=$request->validate(['customer_id'=>'required|exists:customers,id','expected_at'=>'nullable|date','notes'=>'nullable|string|max:4000','items'=>'required|array|min:1','items.*.product_type'=>'required|string|max:120','items.*.paper_grade'=>'nullable|string|max:120','items.*.length'=>'nullable|numeric|min:0|decimal:0,2','items.*.width'=>'nullable|numeric|min:0|decimal:0,2','items.*.height'=>'nullable|numeric|min:0|decimal:0,2','items.*.unit'=>'required|string|max:20','items.*.quantity'=>'required|integer|min:1','items.*.unit_price'=>'required|numeric|min:0|decimal:0,2','items.*.notes'=>'nullable|string|max:1000']); $total=$pricing->orderTotal($v['items']);
        DB::transaction(function()use($id,$v,$total,$pricing,$audit){$order=DB::table('orders')->where('id',$id)->lockForUpdate()->first() ?? abort(404);abort_unless($order->status==='Pending',403,'Orders may only be edited before production begins.');$paid=DB::table('customer_payment_allocations')->join('customer_payments','customer_payments.id','=','customer_payment_allocations.customer_payment_id')->where('customer_payment_allocations.order_id',$id)->whereNull('customer_payments.voided_at')->sum('customer_payment_allocations.amount');abort_if(bccomp((string)$paid,$total,2)>0,422,'Revised order total cannot be lower than payments already allocated.');$before=['customer_id'=>$order->customer_id,'total'=>$order->total,'expected_at'=>$order->expected_at,'notes'=>$order->notes,'items'=>DB::table('order_items')->where('order_id',$id)->get()->toArray()];DB::table('orders')->where('id',$id)->update(['customer_id'=>$v['customer_id'],'total'=>$total,'expected_at'=>$v['expected_at']??null,'notes'=>$v['notes']??null,'updated_at'=>now()]);DB::table('order_items')->where('order_id',$id)->delete();foreach($v['items'] as $item)DB::table('order_items')->insert($item+['order_id'=>$id,'line_total'=>$pricing->lineTotal($item['quantity'],$item['unit_price']),'created_at'=>now(),'updated_at'=>now()]);$audit->record('edited','order',$id,$before,['customer_id'=>$v['customer_id'],'total'=>$total,'items'=>$v['items']]);});return redirect('/?page_name=order&id='.$id)->with('success','Order details updated.');
    }

    public function payment(Request $request, string $type, AuditLogger $audit, \App\Services\DocumentNumber $numbers)
    {
        abort_unless(in_array($type,['customer','supplier']),404); $v=$request->validate(['party_id'=>'required|integer','order_id'=>'nullable|integer','purchase_id'=>'nullable|integer','amount'=>'required|numeric|min:0.01|decimal:0,2','method'=>'required|string|max:40','paid_at'=>'required|date','reference'=>'nullable|string|max:120','notes'=>'nullable|string|max:2000']); $table=$type.'_payments'; $party=$type.'_id';
        $paymentId=DB::transaction(function()use($v,$table,$party,$type,$numbers){ $target=$type==='customer'?'order_id':'purchase_id'; $targetId=$v[$target]??null; if($targetId){$record=DB::table($type==='customer'?'orders':'purchases')->where('id',$targetId)->lockForUpdate()->first(); abort_unless($record && $record->{$type.'_id'}==$v['party_id'],404);$allocTable=$type==='customer'?'customer_payment_allocations':'supplier_payment_allocations';$paymentKey=$type.'_payment_id';$allocated=DB::table($allocTable.' as a')->join($table.' as p','p.id','=','a.'.$paymentKey)->where('a.'.$target,$targetId)->whereNull('p.voided_at')->sum('a.amount'); if(bccomp((string)$v['amount'],bcsub((string)$record->total,(string)$allocated,2),2)>0) abort(422,'Payment exceeds the outstanding balance.');} $id=DB::table($table)->insertGetId([$party=>$v['party_id'],$target=>$targetId,'paid_at'=>$v['paid_at'],'amount'=>$v['amount'],'method'=>$v['method'],'reference'=>$v['reference']??null,'notes'=>$v['notes']??null,'number'=>$numbers->next($type.'_payment',$type==='customer'?'CR':'SP'),'recorded_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]); if($targetId) DB::table($type==='customer'?'customer_payment_allocations':'supplier_payment_allocations')->insert([$type.'_payment_id'=>$id,$target=>$targetId,'amount'=>$v['amount'],'created_at'=>now(),'updated_at'=>now()]); return $id; }); $audit->record('created',$type.'_payment',$paymentId,null,['amount'=>$v['amount'],'method'=>$v['method']]); return back()->with('success','Payment recorded.');
    }

    public function savePurchase(Request $request, \App\Services\DocumentNumber $numbers, AuditLogger $audit)
    {
        $v=$request->validate(['supplier_id'=>'required|exists:suppliers,id','purchased_at'=>'required|date','description'=>'required|string|max:180','total'=>'required|numeric|min:0.01|decimal:0,2','notes'=>'nullable|string|max:2000','initial_payment'=>'nullable|numeric|min:0|decimal:0,2']); abort_if(bccomp((string)($v['initial_payment']??0),(string)$v['total'],2)>0,422,'Initial payment cannot exceed purchase total.'); $id=DB::transaction(function()use($v,$numbers){$id=DB::table('purchases')->insertGetId(['number'=>$numbers->next('purchase','PUR'),'supplier_id'=>$v['supplier_id'],'purchased_at'=>$v['purchased_at'],'description'=>$v['description'],'total'=>$v['total'],'notes'=>$v['notes']??null,'created_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]); if(($v['initial_payment']??0)>0) { $pid=DB::table('supplier_payments')->insertGetId(['number'=>$numbers->next('supplier_payment','SP'),'supplier_id'=>$v['supplier_id'],'purchase_id'=>$id,'paid_at'=>now(),'amount'=>$v['initial_payment'],'method'=>'Cash','recorded_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]); DB::table('supplier_payment_allocations')->insert(['supplier_payment_id'=>$pid,'purchase_id'=>$id,'amount'=>$v['initial_payment'],'created_at'=>now(),'updated_at'=>now()]); } return $id;}); $audit->record('created','purchase',$id,null,['supplier_id'=>$v['supplier_id'],'total'=>$v['total']]); return back()->with('success','Purchase recorded.');
    }

    public function supplierPayment(Request $request, AuditLogger $audit, \App\Services\DocumentNumber $numbers)
    {
        $v=$request->validate(['supplier_id'=>'required|exists:suppliers,id','purchase_id'=>'nullable|exists:purchases,id','paid_at'=>'required|date','amount'=>'required|numeric|min:0.01|decimal:0,2','method'=>'required|string|max:40','reference'=>'nullable|string|max:120','notes'=>'nullable|string|max:2000']);
        $id=DB::transaction(function()use($v,$numbers){$purchase=null;if($v['purchase_id']){$purchase=DB::table('purchases')->where('id',$v['purchase_id'])->lockForUpdate()->first() ?? abort(404);abort_unless($purchase->supplier_id==$v['supplier_id'],422);$allocated=DB::table('supplier_payment_allocations as a')->join('supplier_payments as p','p.id','=','a.supplier_payment_id')->where('a.purchase_id',$purchase->id)->whereNull('p.voided_at')->sum('a.amount');abort_if(bccomp((string)$v['amount'],bcsub((string)$purchase->total,(string)$allocated,2),2)>0,422,'Payment exceeds the outstanding balance.');}$id=DB::table('supplier_payments')->insertGetId(['number'=>$numbers->next('supplier_payment','SP'),'supplier_id'=>$v['supplier_id'],'purchase_id'=>$v['purchase_id']??null,'paid_at'=>$v['paid_at'],'amount'=>$v['amount'],'method'=>$v['method'],'reference'=>$v['reference']??null,'notes'=>$v['notes']??null,'recorded_by'=>auth()->id(),'created_at'=>now(),'updated_at'=>now()]);if($purchase)DB::table('supplier_payment_allocations')->insert(['supplier_payment_id'=>$id,'purchase_id'=>$purchase->id,'amount'=>$v['amount'],'created_at'=>now(),'updated_at'=>now()]);return $id;});$audit->record('created','supplier_payment',$id,null,['amount'=>$v['amount'],'purchase_id'=>$v['purchase_id']??null]);return back()->with('success','Supplier payment recorded.');
    }

    public function allocatePayment(Request $request,string $type,int $id,AuditLogger $audit)
    {
        abort_unless(in_array($type,['customer','supplier']),404);$v=$request->validate(['allocations'=>'required|array|min:1','allocations.*.document_id'=>'required|integer|distinct','allocations.*.amount'=>'required|numeric|min:0.01|decimal:0,2']);$customer=$type==='customer';$payTable=$type.'_payments';$allocTable=$type.'_payment_allocations';$foreign=$type.'_payment_id';$docKey=$customer?'order_id':'purchase_id';$payment=DB::table($payTable)->where('id',$id)->whereNull('voided_at')->first() ?? abort(404);
        DB::transaction(function()use($v,$customer,$type,$payTable,$allocTable,$foreign,$docKey,$id,$payment){$locked=DB::table($payTable)->where('id',$id)->lockForUpdate()->first() ?? abort(404);$already=DB::table($allocTable)->where($foreign,$id)->sum('amount');$remaining=bcsub((string)$locked->amount,(string)$already,2);$submitted='0.00';$ids=[];foreach($v['allocations'] as $entry){$submitted=bcadd($submitted,(string)$entry['amount'],2);$ids[]=(int)$entry['document_id'];}abort_if(bccomp($submitted,$remaining,2)>0,422,'Allocation exceeds the unallocated payment amount.');$docTable=$customer?'orders':'purchases';$docParty=$type.'_id';$docs=DB::table($docTable)->whereIn('id',$ids)->orderBy('id')->lockForUpdate()->get()->keyBy('id');foreach($v['allocations'] as $entry){$doc=$docs->get((int)$entry['document_id']);abort_unless($doc && $doc->{$docParty}==$payment->{$docParty},422,'Selected document does not belong to this party.');abort_if($customer && $doc->status==='Cancelled',422,'Cancelled orders cannot receive payment allocations.');abort_if(!$customer && $doc->status!=='Open',422,'Closed purchases cannot receive payment allocations.');$alreadyForDoc=DB::table($allocTable.' as a')->join($payTable.' as p','p.id','=','a.'.$foreign)->where('a.'.$docKey,$doc->id)->whereNull('p.voided_at')->sum('a.amount');abort_if(bccomp((string)$entry['amount'],bcsub((string)$doc->total,(string)$alreadyForDoc,2),2)>0,422,'Allocation exceeds document balance.');DB::table($allocTable)->insert([$foreign=>$id,$docKey=>$doc->id,'amount'=>$entry['amount'],'created_at'=>now(),'updated_at'=>now()]);}});$audit->record('allocated',$type.'_payment',$id,null,$v['allocations']);return back()->with('success','Payment allocations saved.');
    }

    public function voidPayment(Request $request, string $type, int $id, AuditLogger $audit)
    {
        abort_unless(in_array($type,['customer','supplier']),404); $request->validate(['reason'=>'required|string|min:5|max:1000']); $table=$type.'_payments'; $row=DB::table($table)->where('id',$id)->whereNull('voided_at')->first() ?? abort(404);
        DB::transaction(function()use($table,$row,$id,$request){ DB::table($table)->where('id',$id)->update(['voided_at'=>now(),'voided_by'=>auth()->id(),'void_reason'=>$request->reason,'updated_at'=>now()]); }); $audit->record('voided',$type.'_payment',$id,(array)$row,['reason'=>$request->reason]); return back()->with('success','Payment voided with audit history retained.');
    }

    public function saveSetting(Request $request, AuditLogger $audit)
    {
        abort_unless(auth()->user()->role==='Administrator / Owner',403); $v=$request->validate(['key'=>'required|in:factory_name,factory_address,factory_phone,currency,timezone,document_footer','value'=>'nullable|string|max:1000']); if($v['key']==='timezone')$request->validate(['value'=>'required|timezone']); $before=DB::table('business_settings')->where('key',$v['key'])->value('value'); DB::table('business_settings')->updateOrInsert(['key'=>$v['key']],['value'=>$v['value']??'','updated_at'=>now(),'created_at'=>now()]); $audit->record('setting_changed','business_setting',null,['key'=>$v['key'],'value'=>$before],$v); return back()->with('success','Business setting saved.');
    }

    public function saveUser(Request $request)
    {
        abort_unless(auth()->user()->role==='Administrator / Owner',403); $v=$request->validate(['name'=>'required|string|max:160','email'=>'required|email|unique:users,email','password'=>'required|string|min:12|confirmed','role'=>'required|in:Administrator / Owner,Manager,Accounts Staff,Operational Staff']); DB::table('users')->insert(['name'=>$v['name'],'email'=>$v['email'],'password'=>bcrypt($v['password']),'role'=>$v['role'],'active'=>true,'created_at'=>now(),'updated_at'=>now()]); app(AuditLogger::class)->record('created','user',null,null,['name'=>$v['name'],'email'=>$v['email'],'role'=>$v['role']]); return back()->with('success','Staff account created.');
    }
}
